Write-Host "================================================================" -ForegroundColor Cyan; Write-Host "🔍 AUDITORÍA DE ESTRUCTURA Y ESTADO: ASestud" -ForegroundColor Cyan; Write-Host "================================================================" -ForegroundColor Cyan; $dbFiles = Get-ChildItem -Path . -Recurse -Filter "*.db" -ErrorAction SilentlyContinue; if ($dbFiles) { Write-Host "`n[+] Bases de datos encontradas:" -ForegroundColor Green; foreach ($file in $dbFiles) { $sizeKB = [math]::Round($file.Length / 1KB, 2); Write-Host "    - Ruta: $($file.FullName) | Tamaño: $sizeKB KB" } } else { Write-Host "`n[-] No se encontraron bases de datos (.db) activas." -ForegroundColor Yellow }; Write-Host "`n[+] Archivos de configuración y despliegue:" -ForegroundColor Green; foreach ($cf in @("ASestud_v1.0.0.iss", ".secret_key", "config.py", "app.py")) { if (Test-Path $cf) { Write-Host "    [ENCONTRADO] $cf" -ForegroundColor Cyan } else { Write-Host "    [AUSENTE]    $cf" -ForegroundColor DarkGray } }; Write-Host "`n[+] Estado de carpetas del sistema:" -ForegroundColor Green; foreach ($dir in @("instance", "static\backups", "static\uploads", "static\recibos", "routes", "templates")) { if (Test-Path $dir) { $count = (Get-ChildItem -Path $dir -Recurse -File -ErrorAction SilentlyContinue).Count; Write-Host "    - Carpeta '$dir' existe ($count archivos)." -ForegroundColor Cyan } else { Write-Host "    - Carpeta '$dir' no existe." -ForegroundColor DarkGray } }; Write-Host "`n[+] Estado de Git:" -ForegroundColor Green; if (Test-Path ".git") { $gitStatus = git status -s; $gitBranch = if (git branch --show-current) { git branch --show-current } else { "HEAD desacoplado" }; Write-Host "    - Rama actual: $gitBranch" -ForegroundColor Cyan; if ($gitStatus) { Write-Host "    - Hay cambios locales sin confirmar." -ForegroundColor Yellow } else { Write-Host "    - Repositorio local limpio." -ForegroundColor Cyan } } else { Write-Host "    - No es un repo Git activo." -ForegroundColor Yellow }; Write-Host "`n================================================================" -ForegroundColor Cyan; Write-Host "✨ Inspección finalizada sin alterar ningún archivo." -ForegroundColor Cyan; Write-Host "================================================================" -ForegroundColor Cyan
